import java.util.ArrayList;
import java.util.List;

public class PairwiseFolderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        check("fold sums numbers", 6, PairwiseFolder.fold(List.of(1, 2, 3), 0, (total, n) -> total + n));
        check("fold builds a string", "a!b!", PairwiseFolder.fold(List.of("a", "b"), "", (soFar, s) -> soFar + s + "!"));
        check("fold can change type", 9, PairwiseFolder.fold(List.of("abc", "de", "x", "yz", "q"), 0, (total, s) -> total + s.length()));
        check("fold on an empty list returns the seed", 7, PairwiseFolder.fold(new ArrayList<Integer>(), 7, (total, n) -> total + n));

        check("zip stops at the shorter list", "[a1, b2]",
                PairwiseFolder.zip(List.of("a", "b", "c"), List.of(1, 2), (s, n) -> s + n).toString());
        check("zip on equal lengths", "[4, 10, 18]",
                PairwiseFolder.zip(List.of(1, 2, 3), List.of(4, 5, 6), (a, b) -> a * b).toString());
        check("zip with an empty side", "[]",
                PairwiseFolder.zip(new ArrayList<String>(), List.of(1, 2), (s, n) -> s + n).toString());
        check("zip results can be any type", "[true, false]",
                PairwiseFolder.zip(List.of(3, 2), List.of(1, 9), (a, b) -> a > b).toString());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

