import java.util.ArrayList;
import java.util.List;
import java.util.function.BiFunction;

public class PairwiseFolder {

    public static <T, A> A fold(List<T> items, A seed, BiFunction<A, T, A> step) {
        A accumulator = seed;
        for (T item : items) {
            accumulator = step.apply(accumulator, item);
        }
        return accumulator;
    }

    public static <L, R, O> List<O> zip(List<L> left, List<R> right, BiFunction<L, R, O> combiner) {
        List<O> out = new ArrayList<>();
        int shorter = Math.min(left.size(), right.size());
        for (int i = 0; i < shorter; i++) {
            out.add(combiner.apply(left.get(i), right.get(i)));
        }
        return out;
    }
}
